            for key in result:
                self.assertIn(key, LETTERS)
                self.assertEqual(len(result[key]), 1000)

        def test_max_keys(self):
            random.seed(0)
            result = task_func(len(LETTERS), 5)
            for key in result:
                self.assertIn(key, LETTERS)
                self.assertEqual(result[key], [1, 2, 3, 4, 5])

    unittest.main()
